-- Co-op step E (2026-09-27): new Balance Config fields shared.coop.hostWait (a guest who hears nothing from the host
-- for this long pauses its world and shows "waiting for host") and shared.coop.hostGone (it leaves the room only after
-- this long); shared.coop.hostLost is no longer used. Replaces the `shared.coop` object of the live config_schema,
-- carrying every co-op field (choosingSkills, xpShareK from 0026 and goldSplit from 0028 included).
update public.config_schema set schema = jsonb_set(schema, '{properties,shared,properties,coop}',
  $j${"description":"Co-op","default":{},"type":"object","properties":{"bossHpPerMate":{"default":0.6,"description":"Boss / Guardian / Umbra HP + per extra player","type":"number","minimum":0,"maximum":1},"goldPerKill":{"default":0.1,"description":"Not used any more (guests pick up shared Gold drops); kept so older versions stay valid","type":"number","minimum":0,"maximum":1},"heartShare":{"default":60,"description":"Shared drops: a heart also heals allies this close to the player who took it","type":"number","minimum":0,"maximum":600},"pickTime":{"default":10,"description":"Level-up / chest: seconds to choose before a pick is made for you (the room keeps playing)","type":"number","minimum":0,"maximum":600},"shieldR":{"default":40,"description":"Shield bubble radius while choosing (monsters are pushed out)","type":"number","minimum":0,"maximum":400},"shieldPush":{"default":220,"description":"Shield bubble push speed","type":"number","minimum":0,"maximum":2200},"shieldAfter":{"default":5,"description":"Shield stays this long after choosing (s): time to get moving again, still no damage","type":"number","minimum":0,"maximum":600},"choosingSkills":{"default":1,"description":"Skills, Companion and Shadow Clone keep attacking while their player chooses a level-up / chest (1) or stop (0)","type":"number","minimum":0,"maximum":1},"xpShareK":{"default":0,"description":"EXP per pickup for each player = 1 / (1 + this × other players); 0 = everyone gets it all","type":"number","minimum":0,"maximum":2},"goldSplit":{"default":0,"description":"Gold goes to a team pot (who picked what is shown) split evenly at each Stage end, and a dropped chest to whoever takes it (1); or everyone gets every pickup (0)","type":"number","minimum":0,"maximum":1},"reviveTime":{"default":3,"description":"Seconds standing next to a downed ally to revive them","type":"number","minimum":0,"maximum":600},"reviveRange":{"default":22,"description":"Ally revive distance","type":"number","minimum":0,"maximum":220},"reviveHp":{"default":0.3,"description":"HP after an ally revive","type":"number","minimum":0,"maximum":1},"voteTime":{"default":15,"description":"Route vote time (s); the host breaks ties","type":"number","minimum":0,"maximum":600},"clearWait":{"default":30,"description":"Stage-end: wait for everyone to be ready at most (s)","type":"number","minimum":0,"maximum":600},"hostLost":{"default":5,"description":"Not used any more (see hostWait / hostGone); kept so older versions stay valid","type":"number","minimum":0,"maximum":600},"hostWait":{"default":1.5,"description":"Guest: no host snapshot for this long (s) → its world pauses and \"waiting for host\" shows","type":"number","minimum":0,"maximum":600},"hostGone":{"default":60,"description":"Guest: leave the room after this long (s) without a host snapshot","type":"number","minimum":0,"maximum":600}}}$j$::jsonb)
where id = 1;
